# Authentic 2 (3 bộ). Ảnh tranh + thẻ lấy từ Student's Book (đã cắt sẵn). Script do Claude soạn theo khung các bộ trước
# vì chưa có trang Answer Booklet -> origin "claude". Khi có Answer Booklet, thay script bằng bản của sách và đổi origin về "book".
from sethelp import *
BOOK='Authentic Examination Papers Starters 2'
def src(t): return "%s · hình: Student's Book Test %d Speaking · script do Claude soạn theo khung các bộ trước (chưa có Answer Booklet)"%(BOOK,t)
def cardsdict(sid,items): return {k:card(sid,k,w,s) for k,w,s in items}
def yn(say,vi,h2): return Q(say,vi,['Yes / No'],'',['Yes or no? '+say,h2],free=True)
def what(say,vi,ans,back,alt,point=None): return Q(say,vi,[ans],back,[back,alt],point=point)

